		// A more robust solution would involve a dedicated sanitization library.
		if !isValidLangHeader(infoContent) {
			return header
		}
		newHeader["Accept-Language"] = infoContent
	case "encoding":
		// Basic validation for common encoding types.
		if !isValidEncodingHeader(infoContent) {
			return header
		}
		newHeader["Accept-Encoding"] = infoContent
	case "cache":
		// Basic validation for common cache control directives.
		if !isValidCacheControlHeader(infoContent) {
			return header
		}
		newHeader["Cache-Control"] = infoContent
	default:
		// If infoType is not valid, return the original header map
		return header
	}

	return newHeader
}

